pub fn ucd_lookup(cp: u32) -> (u16, u8, bool, bool, bool) {
    let mut lo = 0usize; let mut hi = UCD_RUNS.len();
    while lo < hi { let mid = (lo + hi) / 2; let r = UCD_RUNS[mid];
        if cp < r.0 { hi = mid; } else if cp >= r.1 { lo = mid + 1; }
        else { return (r.2, r.3, r.4 != 0, r.5 != 0, r.6 != 0); } }
    (0, 29, false, false, false)
}
pub fn decomp_first(cp: u32) -> Option<i32> {
    UCD_DECOMP.binary_search_by_key(&cp, |e| e.0).ok().map(|i| UCD_DECOMP[i].1)
}
